  ui_story_5052_50520101_9_option_content = "¿Dónde estoy?",
  ui_story_5052_50520101_10_dialog_content = "Este lugar se siente un poco familiar, como uno de los <color=#FFB400>orden verdadero</color> lugares de reunión.",
  ui_story_5052_50520101_11_dialog_content = "¿Cómo terminé aquí, de todos modos? Lo último que recuerdo es que estaba caminando por las calles de Umbraton.",
