  ui_story_5052_50520101_20_dialog_content = "Oh, ya veo.",
  ui_story_5052_50520101_21_dialog_content = "Así que fue solo un simple control mental, ¡y pensé que estaba sonámbulo!",
  ui_story_5052_50520101_22_dialog_content = "Pero, ¿por qué me traería aquí?",
  ui_story_5052_50520101_23_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5052_50520101_24_dialog_content = "¿Mmm? ¿Qué fue eso?",
  ui_story_5052_50520101_25_dialog_content = "Este <color=#FFB400>libro</color> también me resulta familiar... ¿Lo he visto antes en alguna parte?",
