  ui_story_5052_50520101_27_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5052_50520101_28_dialog_content = "Las páginas pasan solas. Déjame ver lo que hay en las páginas.",
  ui_story_5052_50520101_29_dialog_content = "Hmmm, me escribieron algunas notas.",
  ui_story_5052_50520101_30_dialog_content = "\"Navegador, a estas alturas ya deberías haberte topado con este mensaje\".",
  ui_story_5052_50520101_31_dialog_content = "\"Estás a punto de enfrentarte a un <color=#FFB400>ensayo</color>, como nunca antes habías experimentado\".",
  ui_story_5052_50520101_32_dialog_content = "\"Pero ten por seguro que el <color=#FFB400>Tomo negro</color> muestra amabilidad a todos sus lectores...\"",
  ui_story_5052_50520101_33_dialog_content = "\"Debes abrazar el cambio si deseas tener éxito, Navegante\".",
  ui_story_5052_50520101_34_dialog_content = "\"Esta nueva prueba es desafiante pero bastante agradable. Incluso yo no pude llegar a su gloriosa conclusión\".",
  ui_story_5052_50520101_35_dialog_content = "“Debemos afrontar cada una de sus pruebas con la mayor devoción y sumisión…”",
  ui_story_5052_50520101_36_dialog_content = "\"No dejes que estos tipos te confundan, PlayerName. Este juicio no es tan complicado como lo hacen parecer\".",
  ui_story_5052_50520101_37_dialog_content = "\"Esto no es más que un capricho pasajero del destino, que ha sido determinado desde hace mucho tiempo\".",
  ui_story_5052_50520101_38_dialog_content = "\"Solo recuerda...\"",
  ui_story_5052_50520101_39_dialog_content = "\"Quemar después de leer.\"",
  ui_story_5052_50520101_40_dialog_content = "\"¿Eh? ¿Por qué tengo que dejarle un mensaje también?",
  ui_story_5052_50520101_41_dialog_content = "\"Sólo escribe algo para mí, ¿quieres? No es como PlayerName realmente lo leerá o algo.\"",
  ui_story_5052_50520101_42_dialog_content = "\"Ustedes son geniales inventando cosas crípticas que nadie entiende. ¡Solo hagan algo así!\"",
  ui_story_5052_50520101_43_dialog_content = "\"Además, es hora de mi té de la tarde. ¡Adiós!\"",
  ui_story_5052_50520101_44_dialog_content = "...",
  ui_story_5052_50520101_45_option_content = "Entendí completamente todo.",
  ui_story_5052_50520101_46_dialog_content = "Sus palabras son tan vagas y confusas como siempre, pero creo que entendí la esencia de las cosas.",
  ui_story_5052_50520101_47_dialog_content = "Estoy aquí para pasar por algún tipo de <color=#FFB400>ensayo</color>, ¿bien?",
  ui_story_5052_50520101_48_dialog_content = "<color=#e8d9bb>Las páginas del libro comienzan a pasar una vez más. De repente, las palabras comienzan a aparecer en una página en blanco...</color>",
  ui_story_5052_50520101_49_dialog_content = "\"Correcto.\"",
  ui_story_5052_50520101_50_option_content = "Seguro que eso era un montón de tonterías.",
