  ui_story_5052_50520101_52_dialog_content = "De todos modos, ¿qué tipo de <color=#FFB400>ensayo</color> estan hablando? ¿Qué quieren decir con \"como nunca antes había experimentado\"?",
  ui_story_5052_50520101_53_dialog_content = "<color=#e8d9bb>Las páginas del libro comienzan a pasar una vez más. De repente, las palabras comienzan a aparecer en una página en blanco...</color>",
