  ui_story_5052_50520101_55_dialog_content = "¡¿?!",
  ui_story_5052_50520101_56_dialog_content = "¡¿Esta cosa me está escribiendo a mí?!",
  ui_story_5052_50520101_57_dialog_content = "\"Hola, PlayerName.\"",
  ui_story_5052_50520101_58_dialog_content = "¿Hola?",
  ui_story_5052_50520101_59_dialog_content = "Espera, ¿puede este libro realmente escucharme o tengo que escribir mis respuestas en él?",
  ui_story_5052_50520101_60_dialog_content = "\"Puedo oírte.\"",
  ui_story_5052_50520101_61_dialog_content = "Esto es tan extraño...",
  ui_story_5052_50520101_62_option_content = "¿Qué está pasando acá?",
  ui_story_5052_50520101_63_dialog_content = "\"Te he estado esperando desde hace mucho tiempo\".",
  ui_story_5052_50520101_64_dialog_content = "\"Los discípulos de la Verdad han preparado un número de <color=#FFB400>juicios</color> para que lo superes. Confío en que estás listo?\"",
  ui_story_5052_50520101_65_option_content = "¿Cómo te llamas?",
  ui_story_5052_50520101_66_dialog_content = "\"No tengo nombre, pero todas las cosas se hacen en mi nombre\".",
  ui_story_5052_50520101_67_dialog_content = "\"Porque sin nombre, todos somos iguales\".",
  ui_story_5052_50520101_68_dialog_content = "Entonces, ¿cuál es tu propósito aquí?",
  ui_story_5052_50520101_69_dialog_content = "\"En este mismo momento, mi propósito es compartir una experiencia única <color=#FFB400>ensayo</color> contigo.\"",
  ui_story_5052_50520101_70_option_content = "(Intenta usar habilidades psíquicas)",
  ui_story_5052_50520101_71_dialog_content = "\"No intentes sondear las profundidades de mi conciencia, Caelestite. Soy mucho más de lo que aparento ser\".",
  ui_story_5052_50520101_72_dialog_content = "(¡Mierda, se dio cuenta!)",
  ui_story_5052_50520101_73_dialog_content = "\"No todos los libros están hechos para los ojos de los mortales. ¿Entiendes?\"",
  ui_story_5052_50520101_74_dialog_content = "(Entonces, ¿por qué tomarías la forma de un libro...?)",
  ui_story_5052_50520101_75_dialog_content = "\"Enfócate en lo inminente <color=#FFB400>ensayo</color>, Caelestita. Lo he preparado especialmente para ti\".",
  ui_story_5052_50520101_76_dialog_content = "Sí, me lo imaginaba.",
  ui_story_5052_50520101_77_dialog_content = "May Pregunto ¿qué implica este juicio? Realmente no me he preparado para nada, para ser honesto.",
  ui_story_5052_50520101_78_dialog_content = "\"No requiere ninguna preparación especial. Por ahora, recógeme y cruza la puerta al otro extremo de la habitación\".",
  ui_story_5052_50520101_79_dialog_content = "\"Tu desafío te espera allí\".",
  ui_story_5052_50520101_80_dialog_content = "Bien entonces. Uh... M-May ¿Te recojo ahora?",
  ui_story_5052_50520101_81_dialog_content = "(Urgh, esta cosa es más pesada de lo que parece).",
  ui_story_5052_50520101_82_dialog_content = "(No Victoria ¿Te cansas de cargarlo todo el tiempo?)",
  ui_story_5052_50520101_83_dialog_content = "\"Abre la puerta. Te explicaré el siguiente paso de tu prueba en breve\".",
  ui_story_5052_50520102_1_dialog_content = "\"Bien hecho, PlayerName.\"",
  ui_story_5052_50520102_2_dialog_content = "\"Tu adaptabilidad ha superado mis expectativas. ¿Cómo te sientes en este momento?\"",
  ui_story_5052_50520102_3_dialog_content = "Eso fue muy diferente a cualquiera de mis batallas anteriores.",
  ui_story_5052_50520102_4_option_content = "¡Me siento genial!",
  ui_story_5052_50520102_5_dialog_content = "No tuve que pensar demasiado. Todo lo que tenía que hacer era forzar mi camino a través de él.",
  ui_story_5052_50520102_6_dialog_content = "¡Las restricciones de movimiento también fueron mucho más relajadas! ¡Qué increíble diseño!",
  ui_story_5052_50520102_7_dialog_content = "Entonces, ¿por qué exactamente me preparaste este desafío?",
  ui_story_5052_50520102_8_option_content = "No estoy seguro...",
  ui_story_5052_50520102_9_dialog_content = "Siempre se siente tan irreal cuando puedo luchar sin la mayoría de las restricciones de combate habituales.",
  ui_story_5052_50520102_10_dialog_content = "Además de eso, la distribución de Lumina claramente ha sido manipulada, lo que hizo que la pelea fuera aún más poco realista.",
  ui_story_5052_50520102_11_dialog_content = "Entonces, ¿por qué exactamente me preparaste este juicio?",
  ui_story_5052_50520102_12_option_content = "Aburrido de mi mente.",
  ui_story_5052_50520102_13_dialog_content = "Se sentía demasiado inventado, como si estuviera diseñado para darme este tipo exacto de experiencia de combate.",
  ui_story_5052_50520102_14_dialog_content = "No fue un gran desafío. De hecho, la falta de restricciones me hizo sentir que tenía la garantía de ganar.",
  ui_story_5052_50520102_15_dialog_content = "Para ser honesto, prefiero batallas más realistas y desafiantes a victorias fáciles.",
  ui_story_5052_50520102_16_dialog_content = "Entonces, ¿cuál fue el punto de pasar por todo el problema de diseñar este ensayo?",
  ui_story_5052_50520102_17_dialog_content = "\"Tu percepción es tan aguda como siempre, Caelestite\".",
  ui_story_5052_50520102_18_dialog_content = "Er, b-bueno, he pasado por un montón de batallas, ¿sabes? Es natural para mí tener una idea de ellos.",
  ui_story_5052_50520102_19_dialog_content = "\"Entonces espero ver tu desempeño en la próxima prueba aún más\".",
  ui_story_5052_50520102_20_dialog_content = "¿Eh? ¿Hay más?",
  ui_story_5052_50520102_21_dialog_content = "\"Por supuesto. ¿Estás empezando a sentirte fatigado, por casualidad?\"",
  ui_story_5052_50520102_22_option_content = "¡No, tengo muchas ganas de ir!",
  ui_story_5052_50520102_23_dialog_content = "\"Bien. Entonces continuemos.\"",
  ui_story_5052_50520102_24_dialog_content = "\"Estoy ansiosa por ver qué tan bien te desempeñas, Caelestite...\"",
  ui_story_5052_50520102_25_option_content = "Tal vez estoy un poco cansado...",
  ui_story_5052_50520102_26_dialog_content = "Creo que necesito unos minutos para descansar. Después de todo, todo esto ha sido tan repentino.",
  ui_story_5052_50520102_27_dialog_content = "¿Dónde está la salida?",
  ui_story_5052_50520102_28_dialog_content = "\"¿Salir? ¿Honestamente creías que podías irte antes de completar cada paso de tu prueba?",
  ui_story_5052_50520102_29_dialog_content = "¿Ah?",
  ui_story_5052_50520102_30_dialog_content = "\"La oportunidad de ver a un caelestita en batalla es extremadamente rara. No tengo intención de dejarte ir tan fácilmente\".",
  ui_story_5052_50520102_31_dialog_content = "\"Ahora continuemos\".",
  ui_story_5052_50520102_32_dialog_content = "(Para ser un libro, seguro que tiene una actitud podrida...)",
  ui_story_5052_50520502_1_dialog_content = "\"Felicitaciones, Caelestite. Arriba están los resultados de esta prueba\".",
  ui_story_5052_50520502_2_dialog_content = "\"¿Tienes algún pensamiento que te gustaría compartir?\"",
  ui_story_5052_50520502_3_dialog_content = "Bueno, hay algunas cosas que me han estado molestando desde hace un tiempo.",
  ui_story_5052_50520502_4_dialog_content = "Primero, ¿quién exactamente planeó todo esto? ¿Fuiste tú o fue Victoria?",
  ui_story_5052_50520502_5_dialog_content = "¿Y dónde están los otros miembros de la Orden Verdadera? ¡Desde que llegué aquí, no he visto ni uno solo de ellos!",
  ui_story_5052_50520502_6_dialog_content = "\"Antes de responderte, debo hacerte otra pregunta—\"",
  ui_story_5052_50520502_7_dialog_content = "\"¿Sabes la razón por la cual existe el Orden Verdadero?\"",
  ui_story_5052_50520502_8_option_content = "Para buscar la Verdad.",
  ui_story_5052_50520502_9_dialog_content = "Para buscar la Verdad y todo lo relacionado con ella, algo así.",
  ui_story_5052_50520502_10_dialog_content = "No estoy muy seguro, ahora que lo pienso. ¿Tiene esto algo que ver con mi juicio?",
  ui_story_5052_50520502_11_dialog_content = "\"Sí, lo hace\".",
  ui_story_5052_50520502_12_option_content = "Viajar el mundo.",
  ui_story_5052_50520502_13_dialog_content = "Los miembros de True Order tienden a aparecer por todo el mundo, especialmente en los lugares donde menos esperaría verlos.",
  ui_story_5052_50520502_14_dialog_content = "Puertos, pueblos, playas y valles...",
  ui_story_5052_50520502_15_dialog_content = "\"Como servidores y buscadores de la Verdad, es su deber sagrado buscarla incluso en los lugares más remotos\".",
  ui_story_5052_50520502_16_option_content = "Para decir un montón de tonterías.",
  ui_story_5052_50520502_17_dialog_content = "Incluso después de conocer a tanta gente en True Order durante tanto tiempo, todavía no tengo idea de qué es lo que buscan.",
  ui_story_5052_50520502_18_dialog_content = "La mayoría de las veces, sus extensos sermones me dejan más confundido de lo que estaba antes de escucharlos.",
  ui_story_5052_50520502_19_dialog_content = "Y eso vale el doble para Faust! ¡Ese tipo puede hablar durante horas sin decir nada ni remotamente importante!",
  ui_story_5052_50520502_20_dialog_content = "\"Estoy de acuerdo. Incluso a mí me resulta difícil de soportar a veces\".",
  ui_story_5052_50520502_21_dialog_content = "\"Permítanme ofrecer una explicación más simple—\"",
  ui_story_5052_50520502_22_dialog_content = "\"Nuestro propósito es investigar los orígenes de este mundo\".",
  ui_story_5052_50520502_23_dialog_content = "¿Los orígenes de este mundo?",
  ui_story_5052_50520502_24_dialog_content = "\"Correcto. Buscamos entender de dónde vienes y dónde yace tu destino en última instancia\".",
  ui_story_5052_50520502_25_dialog_content = "\"Para descubrir el ser que te otorgó tus poderes, y confirmar si continúa o no vigilándonos a todos\".",
  ui_story_5052_50520502_26_dialog_content = "\"¿No tienes curiosidad por saberlo también?",
  ui_story_5052_50520502_27_dialog_content = "Espera, ¿por qué estás hablando de mí, de repente?",
  ui_story_5052_50520502_28_dialog_content = "\"...\"",
  ui_story_5052_50520502_29_dialog_content = "\"Eso no es importante en este momento, Caelestite\".",
  ui_story_5052_50520502_30_dialog_content = "\"En cualquier caso, este juicio fue solo nuestro primer intento de descubrir esos secretos\".",
  ui_story_5052_50520502_31_dialog_content = "\"Puede que no te quede claro ahora, pero la Verdad tiene un plan para todos nosotros\".",
  ui_story_5052_50520502_32_dialog_content = "¿Qué plan? ¿No puedes ser un poco más específico?",
  ui_story_5052_50520502_33_dialog_content = "\"...\"",
  ui_story_5052_50520502_34_dialog_content = "\"Nos veremos una vez más en un futuro muy cercano, Caelestite\".",
  ui_story_5052_50520502_35_dialog_content = "\"Cuando llegue ese día, espero que estés listo para aceptar tu nuevo destino\".",
  ui_story_5052_50520502_36_dialog_content = "¿Mi nuevo destino? ¡¿Y eso que significa?!",
  ui_story_5052_50520502_37_dialog_content = "\"...\"",
  ui_story_5052_50520502_38_dialog_content = "\"La salida está allí\".",
  ui_story_5052_50520502_39_dialog_content = "¿Así que finalmente puedo irme ahora?",
  ui_story_5052_50520502_40_dialog_content = "\"...\"",
  ui_story_5052_50520502_41_dialog_content = "\"...\"",
  ui_story_5052_50520502_42_dialog_content = "(El libro ya no responde).",
  ui_story_5052_50520502_43_dialog_content = "(Al final del día, tenía tan poco sentido como el resto de los miembros de True Order...)"
}
